use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,sync::{Arc,Mutex},time::Instant};
use zopro_bn254::{Fq,Fq2,Fr,G2Affine,G2Projective};
#[path="perf_support.rs"]mod perf;
#[global_allocator]static ALLOCATOR:zopro_core::alloc::Allocator=zopro_core::alloc::Allocator;
fn hash(bytes:&[u8])->String{format!("{:x}",Sha256::digest(bytes))}
fn affinity(cpu:usize){unsafe{let mut mask:libc::cpu_set_t=std::mem::zeroed();libc::CPU_ZERO(&mut mask);libc::CPU_SET(cpu,&mut mask);assert_eq!(libc::sched_setaffinity(0,std::mem::size_of_val(&mask),&mask),0);assert_eq!(libc::sched_getcpu(),cpu as i32);}}
fn point_hash(fields:[Fq;4])->String{let mut h=Sha256::new();for f in fields{for w in f.to_canonical(){h.update(w.to_le_bytes());}}format!("{:x}",h.finalize())}
fn task_count()->usize{fs::read_dir("/proc/self/task").unwrap().count()}

#[cfg(original_control)]fn query(bases:&[G2Affine],words:&mut[[u64;4]])->G2Projective{zopro_core::forward_phi_query_probe(bases,words,false)}
#[cfg(not(original_control))]fn query(bases:&[G2Affine],words:&mut[[u64;4]])->G2Projective{zopro_core::paired_top_query_probe(bases,words)}
#[cfg(original_control)]fn reset(){}
#[cfg(not(original_control))]fn reset(){zopro_core::paired_top_observer::reset();}
#[cfg(original_control)]fn snapshot()->[usize;5]{[0;5]}
#[cfg(not(original_control))]fn snapshot()->[usize;5]{zopro_core::paired_top_observer::snapshot()}
fn route(row:[usize;5],mode:&str,queries:usize){let paired=mode=="paired"||mode=="both";let bundle=mode=="bundled"||mode=="both";assert_eq!(row[0],usize::from(paired)*queries);assert_eq!(row[1],2*usize::from(paired)*queries);assert_eq!(row[2],4*usize::from(bundle)*queries);assert_eq!(row[3]>0,paired);assert_eq!(row[4]>0,bundle);}

fn main(){let args=std::env::args().collect::<Vec<_>>();assert_eq!(args.len(),6,"driver original|bundled|paired|both FIXTURE ORACLE WORKERS ROUNDS");let mode=args[1].as_str();assert!(["original","bundled","paired","both"].contains(&mode));#[cfg(original_control)]assert_eq!(mode,"original");std::env::set_var("ZOPRO_CPU_G2_PAIRED_TOP",if mode=="paired"||mode=="both"{"1"}else{"0"});std::env::set_var("ZOPRO_CPU_INDEXED_TILE_BUNDLES",if mode=="bundled"||mode=="both"{"1"}else{"0"});let workers=args[4].parse::<usize>().unwrap();let rounds=args[5].parse::<usize>().unwrap();assert!([1,16,32].contains(&workers)&&rounds>0);let bytes=fs::read(&args[2]).unwrap();let oracle:Value=serde_json::from_slice(&fs::read(&args[3]).unwrap()).unwrap();assert_eq!(hash(&bytes),oracle["fixture_sha256"]);for flag in["independent_Arkworks_complete_MSM","all_points_in_prime_subgroup","all_points_on_curve","all_scalars_canonical"]{assert_eq!(oracle[flag],true);}assert_eq!(&bytes[..8],b"B2SCAN01");let n=u64::from_le_bytes(bytes[8..16].try_into().unwrap())as usize;assert_eq!(n,oracle["points"]);assert_eq!(bytes.len(),16+160*n);let bases=bytes[16..16+128*n].chunks_exact(128).map(|p|{let fields=p.chunks_exact(32).map(|f|Fq::from_be_bytes(f.try_into().unwrap()).unwrap()).collect::<Vec<_>>();let point=G2Affine::new(Fq2::new(fields[1],fields[0]),Fq2::new(fields[3],fields[2]));assert!(point.is_on_curve());point}).collect::<Vec<_>>();let original=bytes[16+128*n..].chunks_exact(32).map(|s|{let words=core::array::from_fn(|i|u64::from_le_bytes(s[i*8..i*8+8].try_into().unwrap()));assert!(Fr::from_canonical(words).is_some());words}).collect::<Vec<[u64;4]>>();drop(bytes);
let input_hash=||{let mut h=Sha256::new();for point in &bases{for f in[point.x.c0,point.x.c1,point.y.c0,point.y.c1]{for word in f.0{h.update(word.to_le_bytes());}}}format!("{:x}",h.finalize())};let before_hash=input_hash();let seen=Arc::new(Mutex::new(Vec::new()));let seen_start=seen.clone();rayon::ThreadPoolBuilder::new().num_threads(workers).start_handler(move|i|{let cpu=if workers==1{2}else{i};affinity(cpu);seen_start.lock().unwrap().push(json!({"worker":i,"cpu":cpu,"tid":unsafe{libc::syscall(libc::SYS_gettid)}}));}).build_global().unwrap();rayon::broadcast(|ctx|assert_eq!(unsafe{libc::sched_getcpu()},if workers==1{2}else{ctx.index()}as i32));let mut worker_rows=seen.lock().unwrap().clone();worker_rows.sort_by_key(|x|x["worker"].as_u64().unwrap());assert_eq!(worker_rows.len(),workers);let before_tasks=task_count();assert_eq!(before_tasks,workers+1);
let mut words=original.clone();let mut run=||{words.copy_from_slice(std::hint::black_box(&original));let output=query(std::hint::black_box(&bases),std::hint::black_box(&mut words)).to_affine();[output.x.c0,output.x.c1,output.y.c0,output.y.c1]};let check=|fields|assert_eq!(point_hash(fields),oracle["expected_canonical_result_sha256"]);reset();for _ in 0..3{check(run());}route(snapshot(),mode,3);reset();let mut outputs=Vec::with_capacity(rounds);let mut samples=Vec::with_capacity(rounds);let mut control=perf::Control::from_env().unwrap();if let Some(c)=control.as_mut(){c.enable().unwrap();}let before=perf::Usage::now().unwrap();let clock=Instant::now();for _ in 0..rounds{let start=Instant::now();let output=std::hint::black_box(run());samples.push(start.elapsed().as_nanos()as u64);outputs.push(output);}let elapsed=clock.elapsed().as_nanos()as u64;let after=perf::Usage::now().unwrap();if let Some(c)=control.as_mut(){c.disable().unwrap();}let route_metadata=snapshot();route(route_metadata,mode,rounds);for output in outputs{check(output);}check(run());route(snapshot(),mode,rounds+1);rayon::broadcast(|ctx|assert_eq!(unsafe{libc::sched_getcpu()},if workers==1{2}else{ctx.index()}as i32));assert_eq!(before_tasks,task_count());assert_eq!(before_hash,input_hash());println!("CALLER {}",json!({"query":"B","mode":mode,"route_metadata":route_metadata,"route_counts_exact":true,"counter_reset_snapshot_outside_timer":true,"input_rows":n,"workers":workers,"pid":std::process::id(),"rounds":rounds,"priming_passes":3,"postcheck_passes":1,"all_timed_outputs_checked":true,"every_output_matches_independent_full_MSM":true,"point_inputs_unchanged":true,"worker_rows":worker_rows,"default_worker_stacks":true,"one_existing_global_Rayon_pool":true,"tasks_before":before_tasks,"tasks_after":task_count(),"elapsed_ns":elapsed,"ns_per_query":elapsed as f64/rounds as f64,"samples_ns":samples,"B_word_reset_inside_timer":true,"normalization_inside_timer":true,"scalar_split_forward_map_and_alloc_drop_in_query":true,"fixture_sha256":oracle["fixture_sha256"],"expected_canonical_result_sha256":oracle["expected_canonical_result_sha256"],"usage":after.difference(&before),"new_proofs":0}));}
